"""KinDER robot client controller. Public sensors, documented kinematics, and action journal.
Use observe, joints, base, goto, grip; replay reissues the saved actions in order.
"""
from rcb_client import Robot
import numpy as np
import json, argparse
from pathlib import Path
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
OUT=Path('/app/output')
r=Robot(); spec=r.spec()
P=np.array(spec['arm']['position_m']); AX=np.array(spec['arm']['axis'])
EE=np.array(spec['arm']['end_effector']['position_m'])
def fk(q,base=None):
    rot=np.eye(3); pos=P[0].copy()
    for i in range(7):
        if i: pos+=rot@(P[i]-P[i-1])
        rot=rot@Rotation.from_rotvec(AX[i]*q[i]).as_matrix()
    if base is not None:
        rb=Rotation.from_euler('z',base[2]).as_matrix()
        pos=rb@pos+np.r_[base[:2],0]; rot=rb@rot
    return pos,rot

def endpoint(q,base=None,point=EE):
    p,rot=fk(q,base); return p+rot@(point-P[-1]),rot

def camera(q,base,cam='robot_wrist'):
    c=spec['cameras'][cam]['pose']; cp=np.array(c['position_m'])
    R0=np.array([c['right'],c['up'],c['forward']]).T
    if cam=='robot_wrist':
        p,rot=fk(q,base); return p+rot@(cp-P[-1]),rot@R0
    rb=Rotation.from_euler('z',base[2]).as_matrix(); return rb@cp+np.r_[base[:2],0],rb@R0

def observe(name='obs',seconds=0):
    res=r.get_obs(include_depth=True,video='none',seconds=seconds)
    res.save(str(OUT/name)); return res

def state(res): return np.array(res.meta['proprio']['now'])
def save(res,name):
    res.save(str(OUT/name)); (OUT/'latest.json').write_text(json.dumps(res.meta))
    return res

def send(A,name='move'):
    A=np.asarray(A).reshape(-1,11)
    with (OUT/'actions.jsonl').open('a') as f: f.write(json.dumps({'name':name,'actions':A.tolist()})+'\n')
    res=r.submit('delta',A,include_depth=True,video='none',note=name)
    return save(res,name)

def move(q=None,base=None,grip=None,name='move',tol=.006,maxsteps=100):
    res=observe('before'); s=state(res)
    if q is None:q=s[6:13].copy()
    if base is None:base=s[:3].copy()
    if grip is None:grip=1 if s[20]>.1 else 0
    for n in range(maxsteps):
        s=state(res); err=q-s[6:13]; be=base-s[:3]
        if np.max(np.abs(err))<tol and np.max(np.abs(be))<.004:break
        a=np.zeros(11);a[:3]=np.clip(be,-.08,.08); a[3:10]=np.clip(err,-.09,.09);a[10]=grip
        res=send(a,name)
        if res.done:break
    save(res,name); print('steps',n,'state',state(res).round(5).tolist(),'ee',endpoint(state(res)[6:13],state(res)[:3])[0].round(5).tolist(), 'meta',res.meta['control_steps'],res.meta['done'],res.meta['reason'])
    return res

def ik(target,q,base,Rdes=None):
    if Rdes is None:Rdes=np.diag([1,-1,-1])
    def fun(j):
        p,R=endpoint(j,base)
        return np.r_[(p-target)*3,Rotation.from_matrix(Rdes@R.T).as_rotvec()*.7,(j-q)*.008]
    lo=np.array([-15,-2.24,-15,-2.57,-15,-2.09,-15]);hi=np.array([15,2.24,15,2.57,15,2.09,15])
    sol=least_squares(fun,np.clip(q,lo+1e-6,hi-1e-6),bounds=(lo,hi),max_nfev=600,ftol=1e-10,xtol=1e-10,gtol=1e-10)
    p,R=endpoint(sol.x,base);print('IK',sol.x.round(5).tolist(),'position',p.round(5).tolist(),'rot',Rotation.from_matrix(R).as_euler('xyz').round(4).tolist(),'residual',np.linalg.norm(fun(sol.x)[:6]))
    return sol.x

def points(res,cam='robot_wrist'):
    import cv2
    s=state(res);cp,cr=camera(s[6:13],s[:3],cam)
    rgb=res.last[cam]; h,w=rgb.shape[:2]; f=h/(2*np.tan(np.deg2rad(spec['cameras'][cam]['fovy_deg'])/2))
    hsv=cv2.cvtColor(rgb,cv2.COLOR_RGB2HSV)
    masks={'green':((hsv[:,:,0]>35)&(hsv[:,:,0]<90)&(hsv[:,:,1]>80)&(hsv[:,:,2]>45)).astype('uint8'),'red':(((hsv[:,:,0]<12)|(hsv[:,:,0]>170))&(hsv[:,:,1]>100)&(hsv[:,:,2]>35)).astype('uint8')}
    print('camera',cp.round(5).tolist(),cr.round(4).tolist())
    for label,mask in masks.items():
        n,l,stats,cents=cv2.connectedComponentsWithStats(mask)
        for i in range(1,n):
            if stats[i,4]<30:continue
            u,v=cents[i]; d=None
            if cam in res.depth:
                depth=res.depth[cam][-1]; vals=depth[l==i];vals=vals[vals>0]; d=float(np.median(vals)) if len(vals) else None
            ray=cr@np.array([(u-w/2)/f,-(v-h/2)/f,1])
            if d is None:d=(.02-cp[2])/ray[2]
            p=cp+ray*d
            print(label,'uv',np.round([u,v],1).tolist(),'area',int(stats[i,4]),'depth',d,'xyz',p.round(5).tolist())
if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('cmd',nargs='?',default='observe');parser.add_argument('vals',nargs='*',type=float);parser.add_argument('--name',default='obs');parser.add_argument('--grip',type=float);parser.add_argument('--tol',type=float,default=.006);args=parser.parse_args()
    (OUT/'spec.json').write_text(json.dumps(spec,indent=2))
    if args.cmd=='observe':
        res=save(observe(args.name,seconds=args.vals[0] if args.vals else 0),args.name); print(res.meta);points(res);points(res,'robot_base')
    elif args.cmd=='joints':move(q=np.array(args.vals),name=args.name,grip=args.grip,tol=args.tol)
    elif args.cmd=='base':move(base=np.array(args.vals),name=args.name,grip=args.grip,tol=args.tol)
    elif args.cmd=='goto':
        s=state(observe()); q=ik(np.array(args.vals[:3]),s[6:13],s[:3],Rotation.from_euler('xyz',args.vals[3:6]).as_matrix() if len(args.vals)==6 else None);move(q=q,name=args.name,grip=args.grip,tol=args.tol)
    elif args.cmd=='grip':
        a=np.zeros((int(args.vals[1]) if len(args.vals)>1 else 6,11));a[:,10]=args.vals[0];res=send(a,args.name); print(res.meta)
    elif args.cmd=='replay':
        entries=[json.loads(l) for l in (OUT/'actions.jsonl').read_text().splitlines()]
        for e in entries:
            res=r.submit('delta',e['actions'],note=e['name'],video='none')
            if res.done: break
